<?php $edit=query('SELECT * FROM shipping_methods WHERE id=? AND deleted_at IS NULL',[(int)($_GET['id']??0)])->fetch()?:[];$showDeleted=($_GET['deleted']??'')==='1';$values=$edit;if($error&&($_POST['action']??'')==='delivery'){foreach(['name','courier_name','cost','terms','payer','delivery_type'] as $key)if(is_string($_POST[$key]??null))$values[$key]=$_POST[$key];$values['active']=isset($_POST['active'])?1:0;}$pickup=deliveryType($values)==='pickup';?>
<div class="page-title"><div><p class="eyebrow">DOSTAVA I PREUZIMANJE</p><h1>Načini dostave</h1><p>Uredite kurirsku dostavu ili omogućite besplatno lično preuzimanje.</p></div><a class="btn" href="?page=delivery">+ Novi način dostave</a></div>
<?php if(!deliveryTypesReady()):?><p class="notice warning">Za lično preuzimanje napravite backup i uvezite <strong>database/migrations/015_personal_pickup.sql</strong> u postojeću bazu.</p><?php endif;?>
<section class="panel"><h2><?=$edit?'Uredi dostavu':'Dodaj dostavu'?></h2><?php startForm('delivery',(int)($edit['id']??0));?><div data-delivery-method-editor><label for="delivery_type">Vrsta isporuke</label><select id="delivery_type" name="delivery_type" data-method-type><option value="courier" <?=$pickup?'':'selected'?>>Dostava kurirskom službom</option><option value="pickup" <?=$pickup?'selected':''?> <?=deliveryTypesReady()?'':'disabled'?>>Lično preuzimanje — besplatno</option></select><?php field('name','Naziv za kupce',$values['name']??'');?><div data-pickup-info <?=$pickup?'':'hidden'?> class="notice"><strong>Lično preuzimanje · 0,00 KM</strong><p>Kupac preuzima narudžbu u prodavnici. Kurir i trošak se ne unose. U uslove upišite lokaciju, radno vrijeme i način dogovora o preuzimanju.</p></div><fieldset data-courier-fields style="border:0;padding:0;margin:0" <?=$pickup?'disabled hidden':''?>><?php field('courier_name','Kurirska služba (opcionalno)',$values['courier_name']??'','text',false);?><label for="cost">Trošak dostave KM</label><input id="cost" name="cost" type="text" inputmode="decimal" value="<?=e($values['cost']??'10.00')?>" placeholder="npr. 10,00"><p class="field-help">Možete unijeti decimalni zarez ili tačku: 0,00 ili 10.00.</p><?php selectField('payer','Ko plaća dostavu?',deliveryPayers(),$values['payer']??'customer');?></fieldset><?php textField('terms','Uslovi dostave / lokacija i termin ličnog preuzimanja',$values['terms']??'');?><label><input type="checkbox" name="active" <?=!$values||!empty($values['active'])?'checked':''?>> Dostupno kupcima</label><p class="field-help">Lično preuzimanje je uvijek 0,00 KM. Kod kurirske dostave koju plaća prodavac, kupcu je dostava 0 KM. Ranije narudžbe čuvaju već prihvaćene cijene i uslove.</p><button>Spremi dostavu</button></div></form></section>
<section class="panel"><div class="section-heading"><h2><?=$showDeleted?'Obrisani načini dostave':'Registar dostave'?></h2><a href="?page=delivery<?=$showDeleted?'':'&deleted=1'?>"><?=$showDeleted?'Aktivni registar':'Prikaži obrisane'?></a></div><div class="table-scroll"><table><thead><tr><th>Naziv / vrsta isporuke</th><th>Trošak</th><th>Uslovi</th><th>Dostupnost</th><th>Radnje</th></tr></thead><tbody><?php foreach(query('SELECT * FROM shipping_methods WHERE deleted_at IS '.($showDeleted?'NOT NULL':'NULL').' ORDER BY id DESC')->fetchAll() as $d):?><tr><td><strong><?=e($d['name'])?></strong><br><?=deliveryType($d)==='pickup'?'Lično preuzimanje':e($d['courier_name']?:'Kurirska dostava')?></td><td><?=money(deliveryType($d)==='pickup'?0:(float)$d['cost'])?><br><?=e(deliveryPayerLabel($d))?></td><td><?=nl2br(e($d['terms']))?></td><td><?=$d['deleted_at']?'Obrisano':($d['active']?'Dostupno kupcima':'Samo interna priprema')?></td><td><?php if(!$d['deleted_at']):?><a class="table-action" href="?page=delivery&id=<?=$d['id']?>">Uredi</a><details><summary>Obriši</summary><?php startForm('delivery_delete',(int)$d['id']);field('note','Razlog brisanja');?><p class="field-help">Uklanja se iz novog izbora; historija ostaje.</p><button>Potvrdi brisanje</button></form></details><?php else:?><?=e($d['deleted_at'])?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section>
